using TicketClassifier.Services;
using TicketClassifier.Models;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup and register the pooled prediction engine
builder.Services.AddSingleton<ModelTrainingService>();
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>();

var app = builder.Build();

// Train and save the model, then configure the prediction engine pool
var trainer = app.Services.GetRequiredService<ModelTrainingService>();
trainer.TrainAndEvaluate();

app.Services.GetRequiredService<Microsoft.Extensions.ML.PredictionEnginePool<TicketData, TicketPrediction>>();
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(trainer.ModelPath);

// Rebuild with the model file configured
builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<ModelTrainingService>();
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(trainer.ModelPath);

app = builder.Build();

// Train again so metrics are logged (model file already exists from first pass)
app.Services.GetRequiredService<ModelTrainingService>().TrainAndEvaluate();

app.MapControllers();
app.Run();

